function Group317() {
  return (
    <div className="absolute contents left-[140px] top-[7639px]">
      <div className="absolute bg-[rgba(255,255,255,0.21)] h-[984px] left-[140px] rounded-[20px] top-[7639px] w-[1676px]" />
      <div className="absolute bg-[#f5c7a9] h-[984px] left-[140px] rounded-[20px] top-[7639px] w-[371px]" />
      <div className="absolute left-[214px] rounded-[137px] size-[224px] top-[7682px]" data-name="profile image">
        <img alt="" className="absolute inset-0 max-w-none object-cover pointer-events-none rounded-[137px] size-full" src={imgProfileImage} />
      </div>
      <p className="-translate-x-1/2 [word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal leading-[normal] left-[326.5px] text-[#dc7c62] text-[36px] text-center top-[7921px] whitespace-nowrap">Juhi Kapoor</p>
      <p className="[word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal leading-[normal] left-[577px] text-[#005741] text-[36px] top-[7682px] whitespace-nowrap">About</p>
      <p className="[word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal leading-[normal] left-[577px] text-[#005741] text-[36px] top-[7826px] whitespace-nowrap">Coffee Habits</p>
      <p className="-translate-x-1/2 [word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal h-[30px] leading-[normal] left-[326px] text-[#007549] text-[18px] text-center top-[7969px] w-[250px]">25 Years, Female</p>
      <p className="-translate-x-1/2 [word-break:break-word] absolute font-['Exo:SemiBold',sans-serif] font-semibold h-[30px] leading-[normal] left-[326px] text-[#d1512d] text-[22px] text-center top-[8014px] w-[250px]">Visual Designer</p>
      <p className="[word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal leading-[normal] left-[577px] text-[#d1512d] text-[22px] top-[7736px] w-[966px]">Juhi Kapoor is a 25-year-old visual designer hailing from the bustling metropolis of Mumbai. Her creative energy is as vibrant as her city, reflected in her captivating design work.</p>
      <p className="[word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal leading-[normal] left-[577px] text-[#d1512d] text-[22px] top-[8516px] w-[986px]">Overall, Juhi is a discerning coffee drinker who values quality, convenience, and personalization. An ideal coffee app would cater to her specific needs and enhance her daily coffee ritual.</p>
      <ul className="[word-break:break-word] absolute block font-['Exo:Regular',sans-serif] font-normal leading-[0] left-[577px] list-disc text-[#d1512d] text-[22px] top-[7880px] w-[1143px]">
        <li className="leading-[normal] mb-0 ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">Frequency:</span>
          {` Juhi enjoys a daily dose of coffee, typically 1 in the morning and another in the evening.`}
        </li>
        <li className="leading-[normal] mb-0 ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">{`Coffee of Choice: `}</span>
          {` She prefers specialty coffee, particularly pour-over styles that allow her to appreciate the unique flavor profiles of different beans.`}
        </li>
        <li className="leading-[normal] ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">Coffee Rituals:</span>
          {` Grinding her own beans is an important part of Juhi's coffee experience. It's a mindful process that allows her to focus and prepare for the day ahead.`}
        </li>
      </ul>
      <p className="[word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal leading-[normal] left-[577px] text-[#005741] text-[36px] top-[8057px] w-[616px]">Coffee App Needs</p>
      <p className="[word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal leading-[normal] left-[577px] text-[#005741] text-[36px] top-[8462px] w-[616px]">Overall observation</p>
      <ul className="[word-break:break-word] absolute block font-['Exo:Regular',sans-serif] font-normal leading-[0] left-[577px] list-disc text-[#d1512d] text-[22px] top-[8111px] w-[616px]">
        <li className="leading-[normal] mb-0 ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">Speed and Convenience:</span>
          {` Juhi would appreciate an app that allows her to quickly order her preferred coffee beans for delivery or pre-order at her favorite local cafe.`}
        </li>
        <li className="leading-[normal] mb-0 ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">Subscription Service:</span>
          {` A subscription service that delivers fresh, high-quality beans to her doorstep would be ideal.`}
        </li>
        <li className="leading-[normal] mb-0 ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">Personalized Recommendations:</span>
          {` Juhi would love an app that suggests new coffee origins and brewing methods based on her preferences.`}
        </li>
        <li className="leading-[normal] ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">Loyalty Rewards:</span>
          {` An app that rewards her for frequent purchases or lets her earn discounts on coffee equipment would be a plus.`}
        </li>
      </ul>
      <p className="[word-break:break-word] absolute font-['Exo:Regular',sans-serif] font-normal leading-[normal] left-[1259px] text-[#005741] text-[36px] top-[8057px] w-[520px]">Pain Points</p>
      <ul className="[word-break:break-word] absolute block font-['Exo:Regular',sans-serif] font-normal leading-[0] left-[1259px] list-disc text-[#d1512d] text-[22px] top-[8111px] w-[520px]">
        <li className="leading-[normal] mb-0 ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">Limited Time:</span>
          {` Mornings can be hectic, and Juhi finds it frustrating if the coffee brewing process is slow or inconvenient.`}
        </li>
        <li className="leading-[normal] mb-0 ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">{`Inconsistent Quality: `}</span>She dislikes cafes that offer generic coffee or where the quality varies depending on the barista.
        </li>
        <li className="leading-[normal] ms-[33px]">
          <span className="[word-break:break-word] font-['Exo:Bold',sans-serif] font-bold">Hidden Costs:</span>
          {` The cost of daily cafe visits can add up quickly.`}
        </li>
      </ul>
      <TechImage1 />
      <PersonalityImage1 />
    </div>
  );
}

