        <span className="leading-[24px]">{`Gotham is a geometric sans-serif typeface family designed by American type designer Tobias Frere-Jones with Jesse Ragan and released through the Hoefler & Frere-Jones foundry from 2000. Gotham's letterforms were inspired by examples of architectural signs of the mid-twentieth century.`}</span>
